/*
 * smd/test/test_smd_data.c - the SMD module data blocks (source-iv94)
 *
 * Generated by: Claude Opus 5.5
 *
 * smd/smd_data.c is #included, so the blocks under test are the real
 * definitions with the image's initial contents:
 *
 *   SMD_GLOBALS      0x00E82B8C, map "D E82B8C SMD size = 1DA8"
 *   SMD_$WIRED_DATA  0x00E2E3FC, map "D35 E2E3FC SMD_$WIRED_DATA size = 13C"
 *
 * Facts under test:
 *   - SMD_GLOBALS is 0x1DA8 bytes with every field at its A5 displacement
 *     (pointer-free, so this holds on the host too) and carries exactly the
 *     image's non-zero cells;
 *   - its 1-based tables are declared at their bias slots, so the Pascal
 *     index the code computes addresses the image's element:
 *       unit_fonts[i]       A5 + 0x1740 + i*8   (element 1 = 0x1748, the
 *                           pointer SMD_$INIT stores at 0x00E34D6A)
 *       request_queue[k]    A5 + 0x17D0 + k*36  (SMD_$SIGNAL 0x00E6F2DC)
 *       response_pending[u] A5 + 0x1D99 + u     (SMD_$SEND_RESPONSE 0x00E6F4FC)
 *     and each bias slot overlays the object the image has there;
 *   - SMD_$WIRED_DATA is zero in the image and smd_$unit_rec(1) is its one
 *     unit record, directly after the two eventcounts and directly before
 *     the tracking-rectangle lock;
 *   - MODULE_DATA_ADDR gives the image addresses the disassembly uses
 *     (0x00E84924 = default_unit, 0x00E8437C = SMD_REQUEST_QUEUE,
 *     0x00E84926 = SMD_RESPONSE_VAL).
 */

#include <stdio.h>
#include <stdint.h>
#include <string.h>

#include "smd/smd_internal.h"

/* ------------------------------------------------------------------ */
/* Test harness                                                        */
/* ------------------------------------------------------------------ */

static int tests_passed = 0;
static int tests_failed = 0;
static int current_failed = 0;

#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  %-48s", #name);                                             \
        current_failed = 0;                                                   \
        test_##name();                                                        \
        if (current_failed) {                                                 \
            tests_failed++;                                                   \
        } else {                                                              \
            tests_passed++;                                                   \
            printf("PASSED\n");                                               \
        }                                                                     \
    } while (0)

#define CHECK_EQ(expected, actual)                                            \
    do {                                                                      \
        long _e = (long)(expected);                                           \
        long _a = (long)(actual);                                             \
        if (_e != _a) {                                                       \
            if (!current_failed) printf("FAILED\n");                          \
            current_failed = 1;                                               \
            printf("      %s:%d: %s: expected 0x%lx, got 0x%lx\n", __FILE__,  \
                   __LINE__, #actual, (unsigned long)_e, (unsigned long)_a);  \
        }                                                                     \
    } while (0)

/* ------------------------------------------------------------------ */
/* The code under test                                                 */
/* ------------------------------------------------------------------ */

#include "../smd_data.c"

/* Byte offset of a field of SMD_GLOBALS, taken from the object itself. */
#define G_OFF(p) ((long)((const uint8_t *)(p) - (const uint8_t *)&SMD_GLOBALS))

static long count_nonzero_bytes(const void *p, size_t n)
{
    const uint8_t *b = p;
    long count = 0;
    size_t i;

    for (i = 0; i < n; i++) {
        if (b[i] != 0) {
            count++;
        }
    }
    return count;
}

/* ------------------------------------------------------------------ */
/* SMD_GLOBALS: size and layout                                        */
/* ------------------------------------------------------------------ */

static void test_globals_size_is_the_map_segment(void)
{
    CHECK_EQ(0x1DA8, sizeof(SMD_GLOBALS));
    CHECK_EQ(0x00E82B8Cu, MODULE_DATA_ADDR(SMD_GLOBALS));
    /* SMD_GLOBALS + 0x1DA8 is SMD_UTILS (0x00E84934), the next map segment */
    CHECK_EQ(0x00E84934u, MODULE_DATA_ADDR(SMD_GLOBALS) + sizeof(SMD_GLOBALS));
}

static void test_globals_field_displacements(void)
{
    CHECK_EQ(0x0048, G_OFF(&SMD_GLOBALS.asid_to_unit[0]));
    CHECK_EQ(0x00C0, G_OFF(&SMD_GLOBALS.kbd_cursor_track_rect));
    CHECK_EQ(0x00E8, G_OFF(&SMD_GLOBALS.tracking_rects[0]));
    CHECK_EQ(0x072C, G_OFF(&SMD_GLOBALS.event_queue[0]));
    CHECK_EQ(0x1744, G_OFF(&SMD_GLOBALS.cursor_pending_flag));
    CHECK_EQ(0x1788, G_OFF(&SMD_GLOBALS.unit_hdm_list));
    CHECK_EQ(0x178A, G_OFF(&SMD_GLOBALS.unit_hdm_list.blocks[0]));
    CHECK_EQ(0x17F0, G_OFF(&SMD_GLOBALS.request_queue_tail));
    CHECK_EQ(0x17F2, G_OFF(&SMD_GLOBALS.request_queue_head));
    CHECK_EQ(0x1D94, G_OFF(&SMD_GLOBALS.cursor_pos_sentinel));
    CHECK_EQ(0x1D98, G_OFF(&SMD_GLOBALS.default_unit));
    CHECK_EQ(0x1D9C, G_OFF(&SMD_GLOBALS.previous_unit));
    CHECK_EQ(0x1DA0, G_OFF(&SMD_GLOBALS.blink_func[0]));
    CHECK_EQ(0x1DA2, G_OFF(&SMD_GLOBALS.power_off_reported));
}

/* The absolute addresses the disassembly uses for cells of the block. */
static void test_globals_image_addresses(void)
{
    uint32_t base = MODULE_DATA_ADDR(SMD_GLOBALS);

    /* default_unit is the word Ghidra shows as 0x00E84924 */
    CHECK_EQ(0x00E84924u, base + (uint32_t)G_OFF(&SMD_GLOBALS.default_unit));
    /* the map's SMD_REQUEST_QUEUE and SMD_RESPONSE_VAL */
    CHECK_EQ(0x00E8437Cu, base + (uint32_t)G_OFF(&SMD_GLOBALS.request_queue_tail));
    CHECK_EQ(0x00E84926u, base + (uint32_t)G_OFF(&SMD_GLOBALS.response_pending[1]));
    /* blink_func[1], which the image fills with SMD_$BLINK_CURSOR_1 */
    CHECK_EQ(0x00E84930u, base + (uint32_t)G_OFF(&SMD_GLOBALS.blink_func[1]));
}

/* ------------------------------------------------------------------ */
/* SMD_GLOBALS: 1-based tables at their bias slots                     */
/* ------------------------------------------------------------------ */

static void test_font_table_is_one_based(void)
{
    int i;

    /* element i at A5 + 0x1740 + i*8; element 1 is SMD_$INIT's lea 0x1748 */
    for (i = 0; i <= SMD_MAX_FONTS_PER_UNIT; i++) {
        CHECK_EQ(0x1740 + i * 8, G_OFF(&SMD_GLOBALS.unit_fonts[i]));
    }
    CHECK_EQ(0x1748, G_OFF(&SMD_GLOBALS.unit_fonts[1]));
    /* element 8 ends where the HDM free list begins */
    CHECK_EQ(G_OFF(&SMD_GLOBALS.unit_hdm_list),
             G_OFF(&SMD_GLOBALS.unit_fonts[SMD_MAX_FONTS_PER_UNIT + 1]));
    /* the bias slot overlays pad_1740 / cursor_pending_flag / pad_1745 */
    CHECK_EQ(G_OFF(&SMD_GLOBALS.pad_1740[0]), G_OFF(&SMD_GLOBALS.unit_fonts[0]));
    CHECK_EQ(G_OFF(&SMD_GLOBALS.cursor_pending_flag),
             G_OFF(&SMD_GLOBALS.unit_fonts[0].hdm_pos));
}

static void test_request_queue_is_one_based(void)
{
    int k;

    /* SMD_$SIGNAL / SMD_$DM_COND_EVENT_WAIT: A5 + 0x17D0 + k*36, k = 1..40 */
    for (k = 1; k <= SMD_REQUEST_QUEUE_SIZE; k++) {
        CHECK_EQ(0x17D0 + k * 36, G_OFF(&SMD_GLOBALS.request_queue[k]));
    }
    CHECK_EQ(0x17F4, G_OFF(&SMD_GLOBALS.request_queue[1]));
    CHECK_EQ(0x1D70, G_OFF(&SMD_GLOBALS.request_queue[SMD_REQUEST_QUEUE_SIZE]));
    /* entry 40 ends at the cursor sentinel */
    CHECK_EQ(G_OFF(&SMD_GLOBALS.cursor_pos_sentinel),
             G_OFF(&SMD_GLOBALS.request_queue[SMD_REQUEST_QUEUE_SIZE + 1]));
    /* the bias slot's last four bytes are the ring's tail and head words */
    CHECK_EQ(G_OFF(&SMD_GLOBALS.request_queue_tail),
             G_OFF(&SMD_GLOBALS.request_queue[0].params[14]));
    CHECK_EQ(G_OFF(&SMD_GLOBALS.request_queue_head),
             G_OFF(&SMD_GLOBALS.request_queue[0].params[15]));
}

static void test_response_pending_is_one_based(void)
{
    /* SMD_$SEND_RESPONSE / SMD_$BORROW_DISPLAY: A5 + 0x1D99 + unit */
    CHECK_EQ(0x1D99 + 1, G_OFF(&SMD_GLOBALS.response_pending[1]));
    CHECK_EQ(0x1D99 + 2, G_OFF(&SMD_GLOBALS.response_pending[2]));
    /* the bias slot is default_unit's second byte */
    CHECK_EQ(G_OFF(&SMD_GLOBALS.default_unit) + 1,
             G_OFF(&SMD_GLOBALS.response_pending[0]));
    /* and element 2 ends where previous_unit begins */
    CHECK_EQ(G_OFF(&SMD_GLOBALS.previous_unit),
             G_OFF(&SMD_GLOBALS.response_pending[3]));
}

/* ------------------------------------------------------------------ */
/* SMD_GLOBALS: the image's initial contents                           */
/* ------------------------------------------------------------------ */

static void test_globals_initial_contents(void)
{
    static const uint32_t map_length[18] = {
        0x00000000u, 0x00020000u, 0x00020000u, 0x00020000u,
        0x00020000u, 0x00040000u, 0x00020000u, 0x00020000u,
        0x00020000u, 0x00040000u, 0x00020000u, 0x00020000u,
        0x00200000u, 0, 0, 0, 0, 0,
    };
    int i;

    for (i = 0; i < 18; i++) {
        CHECK_EQ(map_length[i], SMD_GLOBALS.display_map_length[i]);
    }
    for (i = 0; i < SMD_MAX_ASIDS; i++) {
        CHECK_EQ(i <= 57 ? 1 : 0, SMD_GLOBALS.asid_to_unit[i]);
    }
    CHECK_EQ(0, SMD_GLOBALS.kbd_cursor_track_rect.x1);
    CHECK_EQ(0x3FFF, SMD_GLOBALS.kbd_cursor_track_rect.x2);
    CHECK_EQ(0, SMD_GLOBALS.kbd_cursor_track_rect.y1);
    CHECK_EQ(0x3FFF, SMD_GLOBALS.kbd_cursor_track_rect.y2);
    CHECK_EQ(1, SMD_GLOBALS.request_queue_tail);
    CHECK_EQ(1, SMD_GLOBALS.request_queue_head);
    CHECK_EQ(0xFFFFFFFFu, SMD_GLOBALS.cursor_pos_sentinel);
    CHECK_EQ(1, SMD_GLOBALS.default_unit);
    CHECK_EQ(-1, SMD_GLOBALS.previous_unit);
    CHECK_EQ(0, SMD_GLOBALS.blink_func[0]);
    /* the host keeps the image's VA of SMD_$BLINK_CURSOR_1 */
    CHECK_EQ(0x00E2722Cu, SMD_GLOBALS.blink_func[1]);

    /*
     * Nothing else is set: the cells above hold 12 (map lengths) + 58
     * (ASID map) + 4 (rectangle) + 2 (ring indices) + 4 (sentinel) +
     * 1 (default_unit) + 2 (previous_unit) + 3 (00 E2 72 2C) = 86 non-zero
     * bytes, in either byte order.
     */
    CHECK_EQ(86, count_nonzero_bytes(&SMD_GLOBALS, sizeof(SMD_GLOBALS)));
}

/* ------------------------------------------------------------------ */
/* SMD_$WIRED_DATA                                                     */
/* ------------------------------------------------------------------ */

static void test_wired_data_is_zero_in_the_image(void)
{
    CHECK_EQ(0x00E2E3FCu, MODULE_DATA_ADDR(SMD_$WIRED_DATA));
    CHECK_EQ(0, count_nonzero_bytes(&SMD_$WIRED_DATA, sizeof(SMD_$WIRED_DATA)));
}

static void test_unit_record_is_unit_one(void)
{
    const uint8_t *base = (const uint8_t *)&SMD_$WIRED_DATA;

    /* unit 1 is the table's only element */
    CHECK_EQ((long)(intptr_t)&SMD_$WIRED_DATA.unit[0], (long)(intptr_t)smd_$unit_rec(1));
    CHECK_EQ(1, SMD_DISPLAY_UNIT_COUNT);
    /* it follows the two eventcounts (+0x18 on the target) ... */
    CHECK_EQ((long)(2 * sizeof(ec_$eventcount_t)),
             (long)((const uint8_t *)smd_$unit_rec(1) - base));
    CHECK_EQ((long)sizeof(ec_$eventcount_t),
             (long)((const uint8_t *)&SMD_$WIRED_DATA.ec_2 - base));
    /* ... and the lock follows it (+0x124 on the target) */
    CHECK_EQ((long)(intptr_t)(smd_$unit_rec(1) + 1),
             (long)(intptr_t)&SMD_$WIRED_DATA.trk_rect_mutex);
}

/* Writes through the accessor land in the block's unit[0].  (The record's
 * displacements hold pointers, so they are asserted on the target only, in
 * smd/smd_internal.h.) */
static void test_unit_record_fields(void)
{
    smd_display_unit_t *rec = smd_$unit_rec(1);

    rec->owner_asid = 0x1234;
    rec->borrowed_asid = 0x5678;
    CHECK_EQ(0x1234, SMD_$WIRED_DATA.unit[0].owner_asid);
    CHECK_EQ(0x5678, SMD_$WIRED_DATA.unit[0].borrowed_asid);
    rec->owner_asid = 0;
    rec->borrowed_asid = 0;
}

int main(void)
{
    printf("SMD module data blocks (SMD_GLOBALS 0x00E82B8C, SMD_$WIRED_DATA 0x00E2E3FC)\n");

    RUN_TEST(globals_size_is_the_map_segment);
    RUN_TEST(globals_field_displacements);
    RUN_TEST(globals_image_addresses);
    RUN_TEST(font_table_is_one_based);
    RUN_TEST(request_queue_is_one_based);
    RUN_TEST(response_pending_is_one_based);
    RUN_TEST(globals_initial_contents);
    RUN_TEST(wired_data_is_zero_in_the_image);
    RUN_TEST(unit_record_is_unit_one);
    RUN_TEST(unit_record_fields);

    printf("\n%d passed, %d failed\n", tests_passed, tests_failed);
    return tests_failed ? 1 : 0;
}
